using System;
using System.Diagnostics;
using System.IO;
using System.Windows.Forms;

namespace PressZeroSetup {
    static class Program {
        private const string EmbeddedExeBase64 = "";

        [STAThread]
        static void Main() {
            try {
                string localAppData = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
                string installDir = Path.Combine(localAppData, "Programs", "PressZero");

                if (!Directory.Exists(installDir)) {
                    Directory.CreateDirectory(installDir);
                }

                string targetExe = Path.Combine(installDir, "PressZero.exe");
                byte[] exeBytes = Convert.FromBase64String(EmbeddedExeBase64);
                File.WriteAllBytes(targetExe, exeBytes);

                // Create Desktop Shortcut
                string desktop = Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);
                string desktopShortcut = Path.Combine(desktop, "PressZero.lnk");
                CreateShortcut(desktopShortcut, targetExe, installDir);

                // Create Start Menu Shortcut
                string startMenu = Environment.GetFolderPath(Environment.SpecialFolder.Programs);
                string startMenuShortcut = Path.Combine(startMenu, "PressZero.lnk");
                CreateShortcut(startMenuShortcut, targetExe, installDir);

                // Create Uninstaller script
                string uninstallerPath = Path.Combine(installDir, "Uninstall.bat");
                string uninstallerContent = "@echo off\r\ndel /f /q \"" + desktopShortcut + "\"\r\ndel /f /q \"" + startMenuShortcut + "\"\r\necho PressZero shortcuts removed.\r\necho To remove files, delete: " + installDir + "\r\npause\r\n";
                File.WriteAllText(uninstallerPath, uninstallerContent);

                DialogResult result = MessageBox.Show(
                    "PressZero has been installed successfully!\n\n" +
                    "• Installed to: " + installDir + "\n" +
                    "• Desktop shortcut created.\n" +
                    "• Start Menu shortcut created.\n\n" +
                    "Would you like to launch PressZero now?",
                    "PressZero Setup",
                    MessageBoxButtons.YesNo,
                    MessageBoxIcon.Information
                );

                if (result == DialogResult.Yes) {
                    Process.Start(new ProcessStartInfo {
                        FileName = targetExe,
                        WorkingDirectory = installDir,
                        UseShellExecute = true
                    });
                }
            } catch (Exception ex) {
                MessageBox.Show("Setup error: " + ex.Message, "PressZero Setup Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        static void CreateShortcut(string shortcutPath, string targetPath, string workingDir) {
            try {
                Type shellType = Type.GetTypeFromProgID("WScript.Shell");
                if (shellType != null) {
                    dynamic shell = Activator.CreateInstance(shellType);
                    dynamic shortcut = shell.CreateShortcut(shortcutPath);
                    shortcut.TargetPath = targetPath;
                    shortcut.WorkingDirectory = workingDir;
                    shortcut.Description = "PressZero - Zero-Knowledge Exact-KB Image Reducer";
                    shortcut.Save();
                }
            } catch {
                // Fallback: non-fatal if COM shortcut fails
            }
        }
    }
}
